UPDATE campus_detection_task
topic_id = #{topicId}, task_name = #{taskName}, object_types = #{objectTypes}, task_status = #{taskStatus}, scan_window_hours = #{scanWindowHours}, auto_alert = #{autoAlert}, next_run_time = #{nextRunTime}, description = #{description}, update_user_id = #{updateUserId}
