  AND deleted = 0

UPDATE campus_detection_task
SET last_run_time = NOW(),
    update_user_id = #{updateUserId}
WHERE detection_task_id = #{detectionTaskId}
  AND deleted = 0

UPDATE campus_detection_task
SET deleted = 1,
    update_user_id = #{updateUserId}
WHERE detection_task_id = #{detectionTaskId}
  AND deleted = 0

